appearances.css:
.app{padding:6px;font-size:10px}
.row{gap:4px;margin:0 0 4px;align-items:flex-end}
.row .control{padding:0;border:0;gap:1px;flex:0 1 auto}
.row .control span{font-size:7.5px;letter-spacing:.04em;text-transform:uppercase}
select,button{font-size:10px;padding:3px 5px;border-radius:4px}
canvas{height:40px;border-radius:4px}
.grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:3px 0;padding:4px 2px;margin-top:4px;border:1px solid var(--line,#344953);border-radius:4px;background:color-mix(in srgb,var(--fg,#d9e6e7) 3%,transparent)}
.grid .control{display:grid;justify-items:center;align-content:start;gap:0;padding:0;border:0;border-radius:0}
.grid .control .kn{order:1;width:28px!important;height:28px!important;justify-self:center!important}
.grid .control .kn svg{width:100%;height:100%}
.grid .control output{order:2;font-size:7.5px;line-height:1.1;color:var(--muted,#aabec5);white-space:nowrap;text-align:center}
.grid .control span{order:3;font-size:7px;letter-spacing:-.02em;line-height:1.1;text-align:center;max-width:100%}
